const proof = `<div style="display:flex;gap:28px"><div style="display:flex;flex-direction:column;gap:6px;padding-right:28px;border-right:1px solid rgba(247,244,239,.18)"><span style="${SERIF};font-size:26px;font-weight:500;color:${PAPER};line-height:1">24h</span><span style="font-size:13px;color:#B9DAD7">respondendo em segundos</span></div><div style="display:flex;flex-direction:column;gap:6px"><span style="${SERIF};font-size:26px;font-weight:500;color:${PAPER};line-height:1">Agenda</span><span style="font-size:13px;color:#B9DAD7">marcada direto na conversa</span></div></div>`;

// ---- form pieces ----
const field = (label, inner, o = {}) => `<div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:13px;font-weight:600;color:${o.error ? '#8A2A21' : MUTED}">${label}</label><div style="height:52px;border-radius:14px;border:1px solid ${o.error ? '#B8483D' : o.focus ? PETROL : '#D6CEC2'};background:#FFFDFA;padding:0 16px;display:flex;align-items:center;gap:10px;font-size:16px;box-sizing:border-box${o.focus ? ';box-shadow:0 0 0 3px #DCECEB' : ''}">${inner}</div>${o.hint ? `<span style="font-size:12px;line-height:1.4;color:${o.error ? '#8A2A21' : FAINT}">${o.hint}</span>` : ''}</div>`;
const email = (o) => field('E-mail', `${I.mail}<span>camila.reis@gmail.com</span>`, o);
