const primary = (t, arrow) => `<div style="height:52px;border-radius:14px;background:${PETROL};color:${PAPER};font-size:16px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:10px;margin-top:4px">${t}${arrow ? I.arrow : ''}</div>`;
const linkRow = (q, a) => `<div style="display:flex;justify-content:center;gap:6px;font-size:14px;color:${MUTED};padding-top:6px">${q}<span style="font-weight:600;color:${PETROL}">${a}</span></div>`;
const backLink = t => `<div style="display:flex;justify-content:center;align-items:center;gap:6px;font-size:14px;font-weight:600;color:${PETROL};padding-top:6px">${I.back}${t}</div>`;
const head = (title, sub) => `<div style="display:flex;flex-direction:column;gap:6px"><h2 style="margin:0;${SERIF};font-size:26px;line-height:1.15;font-weight:500;letter-spacing:-0.01em">${title}</h2>${sub ? `<p style="margin:0;font-size:14px;line-height:1.45;color:${MUTED};text-wrap:pretty">${sub}</p>` : ''}</div>`;
const forgot = strong => `<div style="display:flex;justify-content:flex-end;margin-top:-4px"><span style="font-size:14px;font-weight:600;color:${PETROL}${strong ? ';text-decoration:underline' : ''}">Esqueci minha senha</span></div>`;
const consent = `<div style="display:flex;gap:12px;align-items:flex-start"><span style="width:22px;height:22px;border-radius:7px;background:${PETROL};display:inline-flex;align-items:center;justify-content:center;flex:none;margin-top:1px">${I.check(PAPER)}</span><span style="font-size:13px;line-height:1.45;color:${MUTED}">Li e concordo com os <span style="font-weight:600;color:${PETROL}">Termos de Uso</span> e declaro que li a <span style="font-weight:600;color:${PETROL}">Política de Privacidade</span>.</span></div>`;
